import java.util.*;class VariableRiverGenerationTest{public static void main(String[]args){int n=384;float[] h=new float[n*n];for(int z=0;z<n;z++)for(int x=0;x<n;x++)h[z*n+x]=(float)(180-z*.25+42*Math.exp(-Math.pow((x-207)/18.,2)-Math.pow((z-180)/34.,2)));var flow=EnvironmentNodes.drainage(h,n,()->false);var a=new EnvironmentMap(h.clone());a.water=EnvironmentMap.filled(n*n,62);a.river=new float[n*n];a.material=new byte[n*n];var b=new EnvironmentMap(h.clone());b.water=a.water.clone();b.river=new float[n*n];b.material=new byte[n*n];NaturalRivers.trace(a,h,flow,20*n+192,n,n,62,5,4,Float.POSITIVE_INFINITY,1,2024,.9,.8,.8,()->false);NaturalRivers.trace(b,h,flow,20*n+192,n,n,62,5,4,Float.POSITIVE_INFINITY,1,2024,.9,0,0,()->false);int diff=0,min=999,max=0,ridgeCuts=0;for(int z=30;z<n-15;z++){int width=0,plain=0;for(int x=0;x<n;x++){int i=z*n+x;if(a.river[i]>.1){width++;if(h[i]-(180-z*.25)>25)ridgeCuts++;}if(b.river[i]>.1)plain++;}if(width>0){min=Math.min(min,width);max=Math.max(max,width);}diff+=Math.abs(width-plain);}if(diff<100||max-min<5||ridgeCuts!=0||Arrays.equals(a.height,b.height))throw new AssertionError("Missing natural width/terrain behavior: "+min+".."+max+" difference="+diff+" ridge cuts="+ridgeCuts);System.out.println("PASS: generated river widths "+min+".."+max+" blocks, differs from uniform river, avoids raised ridge core");}}
